55	@RestController
56	@CrossOrigin(exposedHeaders = "errors, content-type")
57	@RequestMapping("/api")
58	public class OwnerRestControllerV1 implements OwnersApi {
59	
60	    /** Dedicated audit logger: on a successful create an audit line records the owner id,
61	     * customerCode and registrationDate. */
62	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
63	
64	    /** Maximum number of owners permitted in a single city; the create is rejected at this count. */
65	    private static final int CITY_CAPACITY = 50;
66	
67	    /** Maximum number of owners that may be created on a single day (by registrationDate); the
68	     * create is rejected once this many owners already carry today's registration date. */
69	    private static final int DAILY_REGISTRATION_LIMIT = 100;
70	
71	    /** Once more than this many owners already carry a given day's registration date, a new owner
72	     * created for that day is flagged with {@code bulkSignupWarning} to signal a bulk-signup surge. */
73	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
74	
75	    private final ClinicService clinicService;
76	
77	    private final OwnerMapper ownerMapper;
78	
79	    private final PetMapper petMapper;
80	
81	    private final VisitMapper visitMapper;
82	
83	    public OwnerRestControllerV1(ClinicService clinicService,
84	                                 OwnerMapper ownerMapper,
85	                                 PetMapper petMapper,
86	                                 VisitMapper visitMapper) {
87	        this.clinicService = clinicService;
88	        this.ownerMapper = ownerMapper;
89	        this.petMapper = petMapper;
90	        this.visitMapper = visitMapper;
91	    }
92	
93	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
94	    @Override
95	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
96	        Collection<Owner> owners;
97	        if (lastName != null) {
98	            owners = this.clinicService.findOwnerByLastName(lastName);
99	        } else {
100	            owners = this.clinicService.findAllOwners();
101	        }
102	        if (owners.isEmpty()) {
103	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
104	        }
105	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
111	        Owner owner = this.clinicService.findOwnerById(ownerId);
112	        if (owner == null) {
113	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
114	        }
115	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
116	    }
117	
118	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
119	    @Override
120	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
121	        HttpHeaders headers = new HttpHeaders();
122	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
123	        // The effective registration date (supplied, or the server date when omitted) must fall on
124	        // a business day: a weekend rolls forward to the next Monday. Everything derived from the
125	        // registration date — the stored value, the per-day limit below and the membership number —
126	        // uses this adjusted date.
127	        LocalDate effectiveDate = BusinessDays.effectiveRegistrationDate(owner.getRegistrationDate());
128	        owner.setRegistrationDate(effectiveDate);
129	        // Per-day capacity: once the day has reached its limit of newly created owners, reject
130	        // further creates for that day with 429 Too Many Requests.
131	        int ownersRegisteredToday = this.clinicService.countOwnersRegisteredOn(effectiveDate);
132	        if (ownersRegisteredToday >= DAILY_REGISTRATION_LIMIT) {
133	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
134	        }
135	        // Bulk-signup warning: flag this owner when more than 80 owners have already been created
136	        // for its registration date, signalling a bulk-signup surge.
137	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
138	        if (this.clinicService.isTelephoneInUse(owner.getTelephone())) {
139	            return new ResponseEntity<>(HttpStatus.CONFLICT);
140	        }
141	        // Per-city capacity: a city that already holds the maximum number of owners is full.
142	        if (this.clinicService.countOwnersInCity(owner.getCity()) >= CITY_CAPACITY) {
143	            return new ResponseEntity<>(HttpStatus.CONFLICT);
144	        }
145	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
146	        boolean householdInUse = this.clinicService.isHouseholdInUse(owner.getLastName(), owner.getAddress());
147	        if (householdInUse) {
148	            if (!sharesHousehold) {
149	                return new ResponseEntity<>(HttpStatus.CONFLICT);
150	            }
151	            // Joining an existing household: assign the shared, stable household identifier to
152	            // the new owner (and back-fill the existing member(s)).
153	            this.clinicService.assignHousehold(owner);
154	        }
155	        // Record the size of the owner's household after this create: the owners already stored
156	        // under the shared household identifier plus this new owner. Owners that do not join a
157	        // household have a size of one (just themselves). This drives the GOLD membership tier.
158	        int householdSize = owner.getHouseholdId() == null ? 1
159	            : this.clinicService.countHouseholdMembers(owner.getHouseholdId()) + 1;
160	        owner.setHouseholdSize(householdSize);
161	        owner.setNamesakeCount(
162	            this.clinicService.countNamesakes(owner.getFirstName(), owner.getLastName()));
163	        this.clinicService.saveOwner(owner);
